import { MeshStandardNodeMaterial, PlaneGeometry, Mesh, Group, Vector2 } from 'three/webgpu';
import { texture, uv, positionLocal, float, vec3, uniform } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-features-list-row';
  group.position.set(-1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.0;
  const height = 0.5;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  const colorMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');

  const parallaxOffset = uniform(new Vector2(0, 0));
  const displacementStrength = uniform(0.06);

  const material = new MeshStandardNodeMaterial();
  const baseUv = uv();
  const depthSample = texture(depthMap, baseUv).r;

  const parallaxUv = baseUv.add(parallaxOffset.mul(depthSample));
  material.colorNode = texture(colorMap, parallaxUv);

  const disp = depthSample.mul(displacementStrength);
  material.positionNode = positionLocal.add(vec3(0.0, 0.0, disp));

  material.metalness = 0.4;
  material.roughness = 0.55;
  material.clearcoat = 0.2;

  const mesh = new Mesh(geometry, material);
  mesh.name = 'hub-features-list-row-plane';
  group.add(mesh);

  // subtle divider line below row
  const dividerGeo = new PlaneGeometry(width, 0.012);
  const dividerMat = new MeshStandardNodeMaterial();
  dividerMat.colorNode = vec3(0.906, 0.925, 0.949); // paper
  dividerMat.metalness = 0.3;
  dividerMat.roughness = 0.6;
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -height / 2 - 0.02, 0.001);
  group.add(divider);

  // accent edge (hidden until focus)
  const accentGeo = new PlaneGeometry(0.02, height);
  const accentMat = new MeshStandardNodeMaterial();
  accentMat.colorNode = vec3(1.0, 0.165, 0.22); // accent
  accentMat.metalness = 0.3;
  accentMat.roughness = 0.5;
  const accentEdge = new Mesh(accentGeo, accentMat);
  accentEdge.position.set(-width / 2 - 0.03, 0, 0.001);
  accentEdge.visible = false;
  group.add(accentEdge);

  // apply parallax primitive since parallax-plane render mode requires cursor/camera parallax
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { strength: 0.15, target: parallaxOffset });
  }

  let timeline = null;
  const baseY = group.position.y;

  function onHover() {
    accentEdge.visible = true;
    if (timeline) timeline.kill();
    timeline = gsap.timeline();
    timeline.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onHoverOut() {
    accentEdge.visible = false;
    if (timeline) timeline.kill();
    timeline = gsap.timeline();
    timeline.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onPointerDown() {
    if (timeline) timeline.kill();
    timeline = gsap.timeline();
    timeline.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
  }

  function onPointerUp() {
    if (timeline) timeline.kill();
    timeline = gsap.timeline();
    timeline.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
    });
  }

  async function onClick() {
    if (ctx.trpc && ctx.trpc.checkout && ctx.trpc.checkout.begin) {
      try {
        const result = await ctx.trpc.checkout.begin.mutate({ itemId: 'hub-features' });
        if (result && result.checkoutUrl && ctx.navigate) {
          ctx.navigate(result.checkoutUrl);
        }
      } catch (e) {
        // swallow — no DOM/console UI available for error surfacing
      }
    }
    if (ctx.emit) {
      ctx.emit('hub-features.select');
    }
  }

  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    pointerDown: onPointerDown,
    pointerUp: onPointerUp,
    click: onClick,
  };

  group.userData.cleanup = function cleanup() {
    if (timeline) timeline.kill();
    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (colorMap && colorMap.dispose) colorMap.dispose();
    if (depthMap && depthMap.dispose) depthMap.dispose();
  };

  return group;
}
